echo "read/doc-99  (no grant, default)     -> "; curl -s -X POST "$BASE/api/decisions" -H "Content-Type: application/json" -d '{"subject":"user-42","action":"document:read","resource":"doc-99"}'; echo
echo "ghost/read/doc-7 (unknown subject)   -> "; curl -s -X POST "$BASE/api/decisions" -H "Content-Type: application/json" -d '{"subject":"ghost","action":"document:read","resource":"doc-7"}'; echo

