  "roles": [ { "name": "Staff", "parent": null } ],
  "assignments": [ { "subject": "user-99", "role": "Staff" } ],
  "grants": [
    { "subject": "user-99", "action": "billing:close", "resource": "acct-1", "effect": "Allow" },
    { "subject": "Staff",   "action": "billing:close", "resource": "acct-1", "effect": "Deny"  }
  ]
}'
